import{_ as e,o as n,c as o,a3 as r}from"./chunks/framework.MGD2uYU7.js";const u=JSON.parse('{"title":"User Stories + Backlog / Task Breakdown — AnPhucRealEstate v1","description":"","frontmatter":{},"headers":[],"relativePath":"guide/10-user-stories-backlog.md","filePath":"guide/10-user-stories-backlog.md","lastUpdated":null}'),i={name:"guide/10-user-stories-backlog.md"};function a(s,t,d,c,g,h){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="user-stories-backlog-task-breakdown-—-anphucrealestate-v1" tabindex="-1">User Stories + Backlog / Task Breakdown — AnPhucRealEstate v1 <a class="header-anchor" href="#user-stories-backlog-task-breakdown-—-anphucrealestate-v1" aria-label="Permalink to &quot;User Stories + Backlog / Task Breakdown — AnPhucRealEstate v1&quot;">​</a></h1><p><strong>Status</strong>: Ready for Sprint 1 — <strong>Author</strong>: Alex (PM) — <strong>Updated</strong>: 2026-10-10 — <strong>v1.4</strong> (US-IDT-05 media foundation DONE — endpoints 64/65/66/67/68, storage OQ-3 chốt SeaweedFS; ảnh dự án hiển thị trên card + gallery detail) — v1.2 (US-HS-01 backend DONE — endpoints 11/12/51 + seed + audit, TC-PRJ-01..09; FE admin dự án tách riêng) — v1.1 (review pass: thêm US-ADM-04 reset password, đồng bộ v2 backlog với non-goals docs/01) <strong>Cách đọc</strong>: Epic → Story (US-&lt;module&gt;-&lt;n&gt;) → Task (BE/FE/QA/Design). Mỗi Story có: Priority (P0/P1/P2), Size (S&lt;1dev-tuần / M / L / XL), Dependencies (story/OC), Acceptance Criteria trỏ docs/09, Definition of Done dùng <strong>DoD chung §4</strong> cộng thêm mục riêng. Sprint 2 tuần, capacity giả định 2 BE + 2 FE + 0.5 QA + 0.5 Design (điều chỉnh khi có team thật — xem §6 note).</p><h2 id="_1-north-star-sprint-goal-theo-milestone" tabindex="-1">1. North Star &amp; Sprint goal theo milestone <a class="header-anchor" href="#_1-north-star-sprint-goal-theo-milestone" aria-label="Permalink to &quot;1. North Star &amp; Sprint goal theo milestone&quot;">​</a></h2><ul><li><strong>North Star v1</strong>: GMV đấu giá hoàn tất (docs/01 §3).</li><li>MS1 goal: &quot;Chủ nhà thật đăng được tin được duyệt, khách thật xem được tin&quot; — US nhóm 1xx–4xx.</li><li>MS2 goal: &quot;1 phiên đấu giá chạy end-to-end với tiền thật&quot; — US nhóm 5xx–6xx.</li><li>MS3 goal: &quot;Sàn tự kiếm tiền + vận hành đo được&quot; — US nhóm 7xx–0xx.</li></ul><h2 id="_2-epics" tabindex="-1">2. Epics <a class="header-anchor" href="#_2-epics" aria-label="Permalink to &quot;2. Epics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Tên</th><th>Milestone</th><th>Stories</th></tr></thead><tbody><tr><td>E1</td><td>Identity thật &amp; hạ tầng</td><td>MS1</td><td>US-IDT-01..05</td></tr><tr><td>E2</td><td>KYC</td><td>MS1</td><td>US-KYC-01..03</td></tr><tr><td>E3</td><td>Housing (dự án + tin + public browse)</td><td>MS1</td><td>US-HS-01..07</td></tr><tr><td>E4</td><td>Admin moderation</td><td>MS1</td><td>US-ADM-01..04</td></tr><tr><td>E5</td><td>Auction engine</td><td>MS2</td><td>US-AU-01..07</td></tr><tr><td>E6</td><td>Payments</td><td>MS2</td><td>US-PAY-01..05</td></tr><tr><td>E7</td><td>Packages / VIP</td><td>MS3</td><td>US-PKG-01..03</td></tr><tr><td>E8</td><td>Viewing</td><td>MS3</td><td>US-VW-01..02</td></tr><tr><td>E9</td><td>Notifications</td><td>MS3</td><td>US-NTF-01..02</td></tr><tr><td>E10</td><td>Admin stats + hardening + GA</td><td>MS3</td><td>US-STA-01..02, US-GA-01..03</td></tr></tbody></table><h2 id="_3-stories-task-breakdown" tabindex="-1">3. Stories + Task Breakdown <a class="header-anchor" href="#_3-stories-task-breakdown" aria-label="Permalink to &quot;3. Stories + Task Breakdown&quot;">​</a></h2><h3 id="e1-—-identity-that-ha-tang-ms1" tabindex="-1">E1 — Identity thật &amp; hạ tầng (MS1) <a class="header-anchor" href="#e1-—-identity-that-ha-tang-ms1" aria-label="Permalink to &quot;E1 — Identity thật &amp; hạ tầng (MS1)&quot;">​</a></h3><p><strong>US-IDT-01</strong> — <em>Là DevOps/BE, tôi cần DB + migration baseline để mọi module có persistence.</em> P0 · M · Deps: OQ-1</p><ul><li>BE: chốt Postgres+ORM; <code>M-000</code> toàn bộ docs/07; docker-compose pg+redis; env validate thêm DATABASE_URL.</li><li>QA: CI job migrate fresh DB; <code>db:rollback:verify</code> script (TC-RB-03).</li><li>DoD thêm: e2e health xanh trên DB thật.</li></ul><p><strong>US-IDT-02</strong> — <em>Là khách, tôi đăng ký/đăng nhập bằng email+password với JWT thật để có tài khoản.</em> P0 · M · Deps: IDT-01 · AC: AC-IDT-01, TC-IDT-01..03</p><ul><li>BE: user entity + repo adapter; register/login use case; <s>thay <code>FAKE_ACCOUNTS</code> trong <code>auth-login.service.ts</code> bằng <code>UserIdentityRepository</code></s> <strong>(DONE — identity module refactor: <code>src/application/services/user.service.ts</code> + Prisma, FAKE_ACCOUNTS đã gỡ)</strong>; password argon2id; seed ADMIN (M-001) <em>(còn lại)</em>; cập nhật e2e hiện hữu.</li><li>BE: JWT RS256 issuer module; <code>@nestjs/throttler</code> limits theo docs/06 §3.</li><li>FE: thay flow login demo hiện tại (<code>features/auth</code>) bằng register form + strength meter (SC-10); route guards <code>(user)</code>.</li><li>QA: TC-IDT-01..03, TC-IDT-06. <strong>US-IDT-03</strong> — Refresh rotation + reuse detection + logout. P0 · S · Deps: IDT-02 · TC-IDT-05. FE: silent-refresh interceptor trong <code>api-client.ts</code> (quy ước: 1 in-flight refresh, queue các request 401). <strong>US-IDT-04</strong> — <code>/auth/me</code>, PATCH profile, đổi mật khẩu. P1 · S · DEPS IDT-02 · SC-29. <strong>US-IDT-05</strong> — Upload media foundation. <strong>DONE (M-003, backend)</strong> — storage OQ-3 chốt SeaweedFS S3; implement là <code>POST /files</code> + <code>GET /files/{id}/url</code> + <code>DELETE /files/{id}</code> (endpoints 64/65/66) và ảnh dự án 67/68 (docs/06 §4.11), KHÔNG phải <code>/media/upload</code> mock cũ (20/21 superseded); MIME allowlist + PUBLIC chỉ ảnh / PRIVATE presigned TTL 15&#39; (BR-IDT-08); resize thumb <strong>chưa làm</strong> (YAGNI v1). TC-IDT-08..10 pass.</li></ul><h3 id="e2-—-kyc-ms1" tabindex="-1">E2 — KYC (MS1) <a class="header-anchor" href="#e2-—-kyc-ms1" aria-label="Permalink to &quot;E2 — KYC (MS1)&quot;">​</a></h3><p><strong>US-KYC-01</strong> — Nộp hồ sơ CCCD. P0 · M · Deps: IDT-05 · AC-KYC-01, TC-KYC-01..04 · BE: kyc entity+machine §10.6, guard KYC_REQUIRED; FE: SC-21 3 bước + crop preview. <strong>US-KYC-02</strong> — Queue + duyệt admin. P0 · M · Deps: KYC-01 · TC-KYC-05..07 · BE: PATCH decision transaction (kyc+user.kyc_status+NTF pending), partial unique APPROVED cccd_hash, signed URL TTL 5&#39;; FE admin: SC-41 table+drawer, SLA badge. <strong>US-KYC-03</strong> — Purge job retention. P2 · S · TC: fake-clock + storage delete; job <code>kyc-purge</code>.</p><h3 id="e3-—-housing-ms1" tabindex="-1">E3 — Housing (MS1) <a class="header-anchor" href="#e3-—-housing-ms1" aria-label="Permalink to &quot;E3 — Housing (MS1)&quot;">​</a></h3><p><strong>US-HS-01</strong> — CRUD dự án (admin) + GET public + seed M-002. P0 · S · Deps: IDT-02 · TC: TC-PRJ-01..09 (docs/09 §2).</p><ul><li>BE: <s>toàn bộ backend</s> <strong>(DONE 2026-10-10 — M-002 migration + aggregate <code>housing-project.ts</code> + endpoints 11/12/51 + audit <code>PROJECT_CREATE</code>/<code>PROJECT_UPDATE</code> theo BR-ADM-01 + seed CLI <code>npm run db:seed:projects</code>; e2e 19 test <code>backend/test/projects.e2e-spec.ts</code>, suite 56 pass)</strong>.</li><li>FE: chưa làm trong commit này — story không breakdown form admin dự án; screen admin CRUD dự án sẽ tách khi làm UI (docs/05).</li><li>OQ-7: chỉ còn blocking <strong>số liệu thật</strong> (cap/dữ liệu từ Ops); dev + e2e chạy trên seed mẫu 10 dự án (idempotent, <code>created_by = NULL</code>). <strong>US-HS-02</strong> — Tạo/sửa DRAFT tin (form wizard). P0 · L · Deps: KYC-02, IDT-05 · AC-HS-01 · BE: aggregate Listing + rich validation (area/price/cap/cert format), unique claim; FE: SC-22 5 bước autosave, realtime cert-check debounce. <strong>US-HS-03</strong> — Submit duyệt + state machine + resubmit limit. P0 · M · Deps: HS-02 · TC-HS-06 matrix generated từ docs/08 §10.1. <strong>US-HS-04</strong> — Quota theo subscription (hàm đọc pkg — tạm hardcode FREE=2 tới MS3). P1 · S · Deps: HS-03 · TC-HS-05 (phần VIP verify lại ở PKG-03). <strong>US-HS-05</strong> — Public list + detail (filter/sort/pagination, masking). P0 · M · Deps: HS-03 · AC-HS-02, TC-HS-07..08 · FE: SC-02/03/04 + gallery + URL-state filters. <strong>US-HS-06</strong> — Owner manage: my listings, withdraw, history decision. P1 · S · TC-HS-10 · SC-23. <strong>US-HS-07</strong> — Media validation nâng cao (count ảnh/docs khi submit, PDF check). P1 · S · TC-HS-09.</li></ul><h3 id="e4-—-admin-moderation-listing-ms1" tabindex="-1">E4 — Admin moderation listing (MS1) <a class="header-anchor" href="#e4-—-admin-moderation-listing-ms1" aria-label="Permalink to &quot;E4 — Admin moderation listing (MS1)&quot;">​</a></h3><p><strong>US-ADM-01</strong> — Queue + approve/reject (re-check cap + cert + <code>cert_owner_name_match</code> bắt buộc khi approve). P0 · M · Deps: HS-03 · AC-ADM-01, TC-ADM-01 · SC-42. <strong>US-ADM-02</strong> — Users admin: search, suspend/activate, BR-IDT-05 guard. P1 · S · DEPS KYC-02 · TC-IDT-06, TC-AU-13 (phần guard) · SC-48. <strong>US-ADM-04</strong> — Reset password user (CS request): endpoint 63 <code>POST /admin/users/{id}/reset-password</code>, temp password 1 lần + force-change gate (<code>password_must_change</code>), revoke refresh family, audit <code>USER_RESET_PASSWORD</code> không lưu mật khẩu; NTF email gửi temp. P1 · S · Deps: IDT-03, NTF-01 (email async; v1 fallback: hiển thị temp trong response cho ADMIN đọc cho user qua hotline — đánh dấu TODO security review) · AC: AC-IDT-03, TC-IDT-07 · SC-48 (nút trong drawer user, modal reason bắt buộc). <strong>US-ADM-03</strong> — Audit log nền (interceptor ghi mutation ADMIN + anti-snipe + manual confirm; append-only grant). P0 · M · Deps: IDT-01 · TC-ADM-02. <strong>Xây sớm — các story sau ghi vào đây.</strong></p><h3 id="e5-—-auction-engine-ms2" tabindex="-1">E5 — Auction engine (MS2) <a class="header-anchor" href="#e5-—-auction-engine-ms2" aria-label="Permalink to &quot;E5 — Auction engine (MS2)&quot;">​</a></h3><p><strong>US-AU-01</strong> — Auction aggregate + state machine + tạo DRAFT + config validate (notice/deadline/duration/step bounds). P0 · M · Deps: HS-06(listing), ADM-03 · AC-AU-01 · SC-45 admin form. <strong>US-AU-02</strong> — Publish/cancel + listing RESERVED/LISTED coupling + partial unique &quot;1 phiên sống/căn&quot;. P0 · M · Deps: AU-01 · TC-AU-01..02, TC-AU-12. <strong>US-AU-03</strong> — Registrations + deposit calc + eligibility (BR-AU-05) + pseudonym. P0 · M · Deps: AU-02, PAY-01 (song song được — mock port) · AC-AU-02, TC-AU-03..05. <strong>US-AU-04</strong> — Bidding core: row-lock transaction, BID_TOO_LOW, rate limit 1/s, idempotency-key, X-Server-Time. P0 · L · Deps: AU-03 · AC-AU-03, TC-AU-05..08, TC-AU-15. <strong>Story xương sống — pre-mortem trước khi code (PM+BE+QA, 1 buổi).</strong><strong>US-AU-05</strong> — Anti-snipe + end job + FAILED/AWARDED + tạo settlement order + NTF events. P0 · L · Deps: AU-04, queue hạ tầng (Redis+BullMQ) · TC-AU-07, TC-AU-09, TC-NFR-J-01. <strong>US-AU-06</strong> — Public browse auctions + detail + live page (upcoming/live/ended, cursor feed). P0 · M · Deps: AU-02 · FE SC-05/06 + countdown server-offset + polling 5s + optimistic bid (docs/05 §4). <strong>US-AU-07</strong> — Settlement member flow: GET orders, pay, EXPIRED job chain (forfeit/privilege/listing). P0 · M · Deps: AU-05, PAY-01 · AC-AU-04, TC-AU-10..11, TC-AU-13 · SC-25.</p><h3 id="e6-—-payments-ms2" tabindex="-1">E6 — Payments (MS2) <a class="header-anchor" href="#e6-—-payments-ms2" aria-label="Permalink to &quot;E6 — Payments (MS2)&quot;">​</a></h3><p><strong>US-PAY-01</strong> — Payment aggregate + intents + <code>PaymentGatewayPort</code> + <strong>VNPay adapter</strong> (OQ-2 chốt trước sprint này — gate). P0 · L · Deps: AU-03 · TC-PAY-01, TC-PAY-05. <strong>US-PAY-02</strong> — Webhook endpoint: checksum, idempotency, dispatch event, RECON_FAILED path. P0 · M · Deps: PAY-01 · TC-PAY-02..03. <strong>US-PAY-03</strong> — Manual transfer path + admin payments screen (confirm, parity event). P0 · M · Deps: PAY-02 · TC-PAY-04, TC-PAY-07 · SC-47. <strong>US-PAY-04</strong> — Refund job (loser 3 ngày làm việc; cancel phiên refund) + retry endpoint. P1 · M · Deps: PAY-02, AU-05 · TC-PAY-06. <strong>US-PAY-05</strong> — Reconciliation CLI + alerting. P2 · S · TC-PAY-02 mở rộng; finance chạy tay tuần đầu GA.</p><h3 id="e7-—-packages-vip-ms3" tabindex="-1">E7 — Packages / VIP (MS3) <a class="header-anchor" href="#e7-—-packages-vip-ms3" aria-label="Permalink to &quot;E7 — Packages / VIP (MS3)&quot;">​</a></h3><p><strong>US-PKG-01</strong> — Packages seed + <code>GET /packages</code> + checkout + subscription machine. P0 · M · Deps: PAY-02 · TC-PKG-01 (full luồng ví dụ nghiệp vụ docs/04 F-06) · SC-07/26. <strong>US-PKG-02</strong> — Quota realtime (bỏ hardcode HS-04) + entitlements (featuredBadge, prioritySort trong <code>GET /housing?sort=featured</code>). P0 · S · Deps: PKG-01, HS-05 · TC-HS-05 phần VIP, TC-PKG-04. <strong>US-PKG-03</strong> — Expiry job + gia hạn/upgrade edge (BR-PKG-03). P1 · S · TC-PKG-02..04.</p><h3 id="e8-—-viewing-ms3" tabindex="-1">E8 — Viewing (MS3) <a class="header-anchor" href="#e8-—-viewing-ms3" aria-label="Permalink to &quot;E8 — Viewing (MS3)&quot;">​</a></h3><p><strong>US-VW-01</strong> — Request + owner actions + jobs. P1 · M · Deps: HS-05, KYC-01 · TC-VW-01..04 · SC-27. <strong>US-VW-02</strong> — NTF 2 chiều + admin oversight list. P2 · S.</p><h3 id="e9-—-notifications-ms3" tabindex="-1">E9 — Notifications (MS3) <a class="header-anchor" href="#e9-—-notifications-ms3" aria-label="Permalink to &quot;E9 — Notifications (MS3)&quot;">​</a></h3><p><strong>US-NTF-01</strong> — Notification core: event bus in-tx record + queue email (provider) + retry/backoff; types FR-NTF-01..05. P1 · M · Deps: queue · TC-NTF-01. <strong>US-NTF-02</strong> — API + bell UI + unread badge + auction reminders (24h/15p job). P1 · M · Deps: NTF-01, AU-05 · TC-NTF-02 · SC-28.</p><h3 id="e10-—-stats-hardening-ga-ms3" tabindex="-1">E10 — Stats + hardening + GA (MS3) <a class="header-anchor" href="#e10-—-stats-hardening-ga-ms3" aria-label="Permalink to &quot;E10 — Stats + hardening + GA (MS3)&quot;">​</a></h3><p><strong>US-STA-01</strong> — <code>GET /admin/stats/overview</code> + cache 5&#39;. P2 · M · Deps: AU-05, PAY-02 · SC-40. <strong>US-STA-02</strong> — Export CSV listings/auctions/orders/users + limit 50k. P2 · S. <strong>US-GA-01</strong> — Load + chaos: k6 suites (TC-NFR-P-01), gateway-down flag <code>payment.provider.down</code> (TC-RB-02), feature flags <code>auction.enabled</code>, <code>marketplace.enabled</code> (TC-RB-01). P0 · M · Deps: AU-07, PAY-03. <strong>US-GA-02</strong> — Security sweep: IDOR matrix TC-SEC-01, XSS/SQLi TC-SEC-02, pentest checklist NFR-S-*; log redact PII. P0 · M. <strong>US-GA-03</strong> — Dry-run auction thật + runbook vận hành (rollback criteria, on-call, CS FAQ, content quy chế + email templates §8 docs/05). P0 · M · <strong>Gate GA docs/01 §8</strong>.</p><h2 id="_4-definition-of-done-chung-moi-story" tabindex="-1">4. Definition of Done (chung mọi story) <a class="header-anchor" href="#_4-definition-of-done-chung-moi-story" aria-label="Permalink to &quot;4. Definition of Done (chung mọi story)&quot;">​</a></h2><ol><li>Code merge vào <code>main</code>, lint + typecheck xanh.</li><li><strong><code>npm run test:e2e</code> PASS 100%, skipped=0</strong> — điều kiện cứng trước commit theo quy trình dự án (hook <code>require_tests.py</code>; cấm <code>--no-verify</code>, cấm skip test).</li><li>Unit tests cho aggregate/state machine (docs/08 §10 transition matrix).</li><li>Swagger <code>@SwaggerApiDocument</code> đủ mọi endpoint mới, khớp docs/06; FE đã confirm hợp đồng (comment trong PR).</li><li>Story docs/09 TC tương ứng xanh + trace <code>Story → TC → test name</code> trong PR.</li><li>Không lệch doc: đổi schema/API/rule → PR update docs/02/06/07/08 cùng lúc (docs/07 §6, docs/08 §12).</li><li>PM/QA review AC trước khi đóng story. Backend cần thêm: observability (traceId, log có cấu trúc).</li></ol><h2 id="_5-milestone-map-sequencing-team-2be-2fe-—-đieu-chinh-§6" tabindex="-1">5. Milestone map &amp; sequencing (team 2BE/2FE — điều chỉnh §6) <a class="header-anchor" href="#_5-milestone-map-sequencing-team-2be-2fe-—-đieu-chinh-§6" aria-label="Permalink to &quot;5. Milestone map &amp; sequencing (team 2BE/2FE — điều chỉnh §6)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sprint</th><th>Week</th><th>Stories</th><th>Gate cuối sprint</th></tr></thead><tbody><tr><td>S1</td><td>1–2</td><td>IDT-01, IDT-02, ADM-03(skeleton audit)</td><td>login DB-thật e2e xanh</td></tr><tr><td>S2</td><td>3–4</td><td>IDT-03, IDT-05, KYC-01, HS-01</td><td>KYC submit mock-admin pass</td></tr><tr><td>S3</td><td>5–6</td><td>KYC-02, HS-02, HS-03, HS-04</td><td><strong>MS1 gate</strong>: pilot 20 tin LISTED qua flow đủ</td></tr><tr><td>S4</td><td>7–8</td><td>ADM-01, ADM-02, ADM-04, HS-05, HS-06</td><td>public site demo được cho Ops</td></tr><tr><td>S5</td><td>9–10</td><td>AU-01, AU-02, PAY-01 (OQ-2 gate), AU-03</td><td>version đấu giá nội bộ DRAFT→PUBLISHED</td></tr><tr><td>S6</td><td>11–12</td><td>AU-04, AU-05, PAY-02</td><td><strong>MS2-a</strong>: bid engine pass TC-AU-04..08</td></tr><tr><td>S7</td><td>13–14</td><td>AU-06, AU-07, PAY-03, PAY-04</td><td><strong>MS2 gate</strong>: dry-run F-00+F-03 đầu tiên (tài khoản nội bộ)</td></tr><tr><td>S8</td><td>15–16</td><td>PKG-01..03, NTF-01, HS-07, VW-01, KYC-03</td><td>VIP flow pass TC-PKG-01</td></tr><tr><td>S9</td><td>17–18</td><td>VW-02, NTF-02, STA-01..02, GA-01</td><td>load suite xanh</td></tr><tr><td>S10</td><td>19–20</td><td>GA-02, GA-03</td><td><strong>GA gate docs/09 §4</strong></td></tr><tr><td>S11</td><td>21–22</td><td>Buffer + pilot + fix</td><td>GA public 20%→100%</td></tr></tbody></table><p><strong>Phát hành &amp; rollout (tóm tắt GTM)</strong>: pilot 10 user nội bộ (MS1) → 50 user mời + 1 phiên dry-run (MS2) → GA web, flags: <code>marketplace.enabled</code> bật trước, <code>auction.enabled</code> sau dry-run pass, <code>payment.provider=manual</code> fallback nếu OQ-2 trễ. rollback criteria docs/09 §5 + docs/01 §8 gate.</p><h2 id="_6-dependencies-assumptions-ghi-cho-planner" tabindex="-1">6. Dependencies &amp; assumptions ghi cho planner <a class="header-anchor" href="#_6-dependencies-assumptions-ghi-cho-planner" aria-label="Permalink to &quot;6. Dependencies &amp; assumptions ghi cho planner&quot;">​</a></h2><ul><li>Capacity là <strong>giả định</strong> (2BE/2FE, 2 tuần/sprint); rebase khi có headcount thật — ưu tiên P0 giữ nguyên thứ tự.</li><li><strong>Blocking-external</strong>: OQ-1 (S1), OQ-3 (S2), OQ-2 (S5), OQ-4 (S5 — text quy chế), OQ-7 (S3 data seed), OQ-8 (S8 giá VIP), Figma (S2 — FE cần token + mockup SC-02/03 trước S4).</li><li>Mobile (Flutter): <strong>không có story v1</strong>; sau GA, API docs/06 đóng băng 2 tuần rồi mobile sprint.</li><li>Story nào estimate &gt; XL → tách trước khi vào sprint (thường AU-04/AU-05).</li></ul><h2 id="_7-backlog-later-—-v2-khong-sched-co-signal-moi-promote" tabindex="-1">7. Backlog &quot;Later&quot; — v2 (không sched, có signal mới promote) <a class="header-anchor" href="#_7-backlog-later-—-v2-khong-sched-co-signal-moi-promote" aria-label="Permalink to &quot;7. Backlog &quot;Later&quot; — v2 (không sched, có signal mới promote)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Signal needed</th></tr></thead><tbody><tr><td><strong>Toàn bộ đề xuất AI</strong> (gợi ý căn, AVM định giá, xếp hạng tìm kiếm, detect ảnh lỗi khi duyệt) — <em>chỉ đạo người dùng 2026-10-09: để ver sau</em></td><td>v1 GA + 90 ngày data hành vi (search logs, bid patterns) + PM viết Opportunity Assessment</td></tr><tr><td>WebSocket live bidding</td><td>p95 poll path &gt; 2× NFR, hoặc phàn nàn pilot</td></tr><tr><td>Quên mật khẩu email reset (self-service)</td><td>volume ticket CS — v1 thay bằng ADMIN reset US-ADM-04/FR-IDT-07</td></tr><tr><td>OTP phone login</td><td>OQ-5 + fraud rate</td></tr><tr><td>Auctioneer tự động giải nhì khi winner vi phạm (BR-AU-18 nới)</td><td>pháp chế OQ-4 xong + pilot demand</td></tr><tr><td>Chủ nhà tự mở phiên</td><td>nguồn cung thiếu + pháp chế</td></tr><tr><td>Tích hợp dữ liệu dân cư / xác minh sổ tự động</td><td>hợp tác cơ quan + chi phí</td></tr><tr><td>Hóa đơn điện tử phí sàn</td><td>OQ-6</td></tr></tbody></table>',40)])])}const p=e(i,[["render",a]]);export{u as __pageData,p as default};
